**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <queue>
using namespace std;

const int N = 8;
char tab[N][N];
bool visited[N][N];
int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};

int bfs(int si, int sj) {
    queue<pair<int,int>> q;
    q.push({si, sj});
    visited[si][sj] = true;
    int rozmiar = 0;
    while (!q.empty()) {
        auto [i, j] = q.front(); q.pop();
        rozmiar++;
        for (int d = 0; d < 4; d++) {
            int ni = i + dx[d], nj = j + dy[d];
            if (ni >= 0 && ni < N && nj >= 0 && nj < N
                && !visited[ni][nj] && tab[ni][nj] == '#') {
                visited[ni][nj] = true;
                q.push({ni, nj});
            }
        }
    }
    return rozmiar;
}

int main() {
    ifstream plik("mapa.txt");
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            plik >> tab[i][j];

    vector<int> rozmiary;
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            if (tab[i][j] == '#' && !visited[i][j])
                rozmiary.push_back(bfs(i, j));

    cout << "a) Liczba wysp: " << rozmiary.size() << endl;
    cout << "b) Rozmiary:";
    for (int r : rozmiary) cout << " " << r;
    cout << endl;

    int maxR = 0, maxIdx = 0;
    for (int k = 0; k < (int)rozmiary.size(); k++)
        if (rozmiary[k] > maxR) { maxR = rozmiary[k]; maxIdx = k; }
    cout << "c) Najwieksza wyspa: " << maxIdx + 1 << endl;
    return 0;
}
```

**Wyjasnienie**: BFS znajduje kazdy spojny obszar '#'. Iterujemy po siatce, gdy natrafimy na nieodwiedzony '#', uruchamiamy BFS i zapisujemy rozmiar.

